const tabId = 248688717;
const sectionDetails = await browserjs(tabId, () => {
  // Let's find all filter sections and their options
  const results = {};
  const sections = Array.from(document.querySelectorAll('li, div')).filter(el => {
    return el.querySelector('button[aria-expanded]') && el.querySelector('ul, [role="list"]');
  });

  for (const s of sections) {
    const btn = s.querySelector('button[aria-expanded]');
    const name = btn ? btn.innerText.trim() : 'Unknown';
    const items = Array.from(s.querySelectorAll('a')).map(a => ({
      text: a.innerText.trim().replace(/\n/g, ' '),
      href: a.href
    }));
    if (items.length > 0 && !results[name]) {
      results[name] = items;
    }
  }
  return results;
});
console.log(JSON.stringify(sectionDetails, null, 2));

