const tabId = 248688717;
const brandInfo = await browserjs(tabId, () => {
  // find the Brand heading/button
  const buttons = Array.from(document.querySelectorAll('button'));
  const brandBtn = buttons.find(b => b.innerText.trim() === 'Brand');
  if (!brandBtn) return { error: 'Brand button not found' };

  // Find the container for Brand
  let container = brandBtn.closest('li') || brandBtn.parentElement;
  let seeMoreBtn = container.querySelector('button.psFZtc') || Array.from(container.querySelectorAll('button')).find(b => b.innerText.includes('more'));

  const currentBrands = Array.from(container.querySelectorAll('a')).map(a => a.innerText.trim());
  return {
    brandBtnText: brandBtn.innerText,
    currentBrands,
    seeMore: seeMoreBtn ? seeMoreBtn.innerText : null
  };
});
console.log(JSON.stringify(brandInfo, null, 2));

