const tabId = 248688717;
const products = await browserjs(tabId, () => {
  // Let's find all product cards/items
  const items = [];
  // Look for product containers or buttons with product descriptions
  const buttons = Array.from(document.querySelectorAll('button')).filter(b => {
    return b.innerText && (b.innerText.includes('Current Price') || b.getAttribute('aria-label')?.includes('Current Price'));
  });

  for (const b of buttons) {
    const text = b.getAttribute('aria-label') || b.innerText;
    items.push(text.replace(/\n/g, ' '));
  }

  // Also check general cards if buttons didn't catch all
  const cards = Array.from(document.querySelectorAll('div[data-docid], div.sh-dgr__content, div[data-item-id]')).map(c => c.innerText.replace(/\n/g, ' '));

  return { buttonItems: items, cardCount: cards.length, sampleCards: cards.slice(0, 5) };
});
console.log("Found buttonItems:", products.buttonItems.length);
console.log(JSON.stringify(products.buttonItems, null, 2));

