const tabId = 248688717;
const snapshot = await browser.snapshot({ tabId });
const lines = snapshot.text.split('\n');

const buttonRegex = /button "(.*?)" \[ref=(.*?)\]/;
const products = [];

for (const line of lines) {
  const match = line.match(buttonRegex);
  if (match) {
    const text = match[1];
    const ref = match[2];
    if (text.includes('Current Price:') || text.includes('Go to product viewer')) {
      products.push({ text, ref });
    }
  }
}

console.log(`Parsed ${products.length} products:`);
for (const p of products) {
  console.log(`- [${p.ref}] ${p.text}`);
}

